import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1791960929000}'),o={name:"faq.md"};function s(i,e,l,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><h2 id="do-i-need-erpnext" tabindex="-1">Do I need ERPNext? <a class="header-anchor" href="#do-i-need-erpnext" aria-label="Permalink to &quot;Do I need ERPNext?&quot;">​</a></h2><p>Yes. SSPL Billing runs on Frappe / ERPNext v16. If you don&#39;t run ERPNext yet, we install and configure it as part of implementation.</p><h2 id="can-it-run-on-my-own-server" tabindex="-1">Can it run on my own server? <a class="header-anchor" href="#can-it-run-on-my-own-server" aria-label="Permalink to &quot;Can it run on my own server?&quot;">​</a></h2><p>Yes. It runs on any Linux server that can run ERPNext. We can also host it for you.</p><h2 id="does-it-work-without-internet" tabindex="-1">Does it work without internet? <a class="header-anchor" href="#does-it-work-without-internet" aria-label="Permalink to &quot;Does it work without internet?&quot;">​</a></h2><p>The application runs on your local network. Item and customer search uses a browser cache, so lookups stay fast even on slow connections. Saving bills needs a connection to the server.</p><h2 id="how-many-counters-can-bill-at-the-same-time" tabindex="-1">How many counters can bill at the same time? <a class="header-anchor" href="#how-many-counters-can-bill-at-the-same-time" aria-label="Permalink to &quot;How many counters can bill at the same time?&quot;">​</a></h2><p>There is no limit from the software. Each counter is a browser tab; draft bills from all counters appear at the Cashier Desk.</p><h2 id="can-i-restrict-what-each-user-sees" tabindex="-1">Can I restrict what each user sees? <a class="header-anchor" href="#can-i-restrict-what-each-user-sees" aria-label="Permalink to &quot;Can I restrict what each user sees?&quot;">​</a></h2><p>Yes. An administrator chooses which dashboard tiles each user can open. Billers, cashiers and accounts staff each get their own set of screens.</p><h2 id="which-printers-are-supported" tabindex="-1">Which printers are supported? <a class="header-anchor" href="#which-printers-are-supported" aria-label="Permalink to &quot;Which printers are supported?&quot;">​</a></h2><p>Any printer that works with the browser, including thermal receipt printers and A4 laser printers. Each document type can be mapped to its own printer and print format.</p><h2 id="can-i-upgrade-my-plan-later" tabindex="-1">Can I upgrade my plan later? <a class="header-anchor" href="#can-i-upgrade-my-plan-later" aria-label="Permalink to &quot;Can I upgrade my plan later?&quot;">​</a></h2><p>Yes. Additional modules are unlocked by updating the licence — no reinstall, and your data stays as it is.</p><h2 id="how-is-pricing-calculated" tabindex="-1">How is pricing calculated? <a class="header-anchor" href="#how-is-pricing-calculated" aria-label="Permalink to &quot;How is pricing calculated?&quot;">​</a></h2><p>See <a href="./pricing">Pricing</a>. The final quote depends on the number of users, stores and modules you need.</p>',17)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
